# Proxy profile: one POST to the proxy, which adds the FileMaker credentials itself.
# Replace the modId with the one from the record you read.
curl -X POST 'https://proxy.example.com/filemaker' -H 'Content-Type: application/json' -H 'Authorization: Bearer <REDACTED>' --data-raw '{"action":"editRecord","profile":{"id":"profile-proxy","database":"Sales DB","serverUrl":"https://fm.example.com"},"payload":{"layout":"Contacts","recordId":"42","fieldData":{"Status":"Inactive"},"modId":"<modId>"}}'